// Make Code module — builds the HubSpot batch line-item body.
// Inputs are exposed as properties of the `input` object.

const lineItemsRaw = input.lineItems;
const dealIdRaw = input.dealId;
const currencyRaw = input.currency;

const items = Array.isArray(lineItemsRaw) ? lineItemsRaw : [];
const deal = String(dealIdRaw || "").trim();
const curr = (currencyRaw || "USD").trim();

if (!deal) {
    throw new Error("Missing dealId — cannot build line item associations.");
}

function toNumber(val) {
    if (val === null || val === undefined || val === "") return null;
    const cleaned = String(val).replace(/[^0-9.\-]/g, "");
    const n = parseFloat(cleaned);
    return isNaN(n) ? null : n;
}

const inputs = [];

for (const item of items) {
    const props = (item && item.properties) ? item.properties : {};
    const name = (props.name ? String(props.name) : "").trim();
    if (!name) continue;

    const quantity = toNumber(props.quantity);
    const price = toNumber(props.price);

    const properties = {
        name: name,
        hs_line_item_currency_code: curr
    };
    if (quantity !== null) properties.quantity = quantity;
    if (price !== null) properties.price = price;

    inputs.push({
        properties: properties,
        associations: [
            {
                to: { id: deal },
                types: [
                    {
                        associationCategory: "HUBSPOT_DEFINED",
                        associationTypeId: 20
                    }
                ]
            }
        ]
    });
}

const body = { inputs: inputs };

return {
    bodyString: JSON.stringify(body),
    count: inputs.length
};
